function panel(n){if(L.panelImages?.[n-1]){const path=L.panelImages[n-1],src=window.LESSON_ASSETS?.[path]||path,r=L.panelRects[n-1];return `<div class="panel panel-direct"><img src="${esc(src)}" alt="原有漫画第${n}格" width="${r[2]}" height="${r[3]}" loading="eager" decoding="async"></div>`}const r=L.panelRects[n-1],sheet=L.panelSheets?.[n-1]||Math.ceil(n/10),src=window.LESSON_ASSETS?.['comic'+sheet]||'assets/comic'+sheet+'.png';return `<div class="panel" style="aspect-ratio:${r[2]}/${r[3]}"><img src="${src}" alt="原有漫画第${n}格" style="width:${1024/r[2]*100}%;left:${-r[0]/r[2]*100}%;top:${-r[1]/r[3]*100}%" loading="lazy"></div>`}
